function fOpcionesMiCuenta(){var domContenido,oParametros,sRuta;try{domContenido=document.getElementById("contenido-opciones-mi-cuenta");domContenido!==null&&domContenido!==undefined&&(oParametros={},sRuta="/opciones-mi-cuenta",fetch(sRuta,{method:"POST",headers:{"Content-type":"application/json",Accept:"application/json"},body:JSON.stringify(oParametros)}).then(function(oRespuesta){oRespuesta.json().then(function(jRespuesta){jRespuesta.bCorrecto?(domContenido.innerHTML=jRespuesta.sHtml,domContenido.dataset.relleno="true"):console.error(jRespuesta.sMotivo)})}).catch(function(){console.error("No pudimos conectar con el servidor, por favor, inténtelo de nuevo más tarde")}))}catch(error){console.error("No pudimos conectar con el servidor, por favor, inténtelo de nuevo más tarde")}}function fOpcionesMenuMovil(){var domContenido,oParametros,sRuta;try{domContenido=document.getElementById("contenido-menu-movil");domContenido!==null&&domContenido!==undefined&&(oParametros={},sRuta="/opciones-mi-cuenta",fetch(sRuta,{method:"POST",headers:{"Content-type":"application/json",Accept:"application/json"},body:JSON.stringify(oParametros)}).then(function(oRespuesta){oRespuesta.json().then(function(jRespuesta){jRespuesta.bCorrecto?(domContenido.innerHTML=jRespuesta.sHtml,domContenido.dataset.relleno="true"):console.error(jRespuesta.sMotivo)})}).catch(function(){console.error("No pudimos conectar con el servidor, por favor, inténtelo de nuevo más tarde")}))}catch(error){console.error("No pudimos conectar con el servidor, por favor, inténtelo de nuevo más tarde")}}